-- deployment-mode: maintenance
-- Make normalized Plugin/Version/Facet installations authoritative for Skills,
-- Plugins, and Integration Definitions, and keep Packs authoritative in their
-- dedicated installation ledger. Exact active curated Skill selections are
-- materialized from the reviewed immutable library before every non-MCP row is
-- retired from the generic catalog/installations compatibility ledger.

SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '30min';

DO $maintenance_preflight_guard$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'opengeni_app')
    AND EXISTS (
      SELECT 1
      FROM pg_stat_activity
      WHERE datname = current_database()
        AND usename = 'opengeni_app'
        AND pid <> pg_backend_pid()
    )
  THEN
    RAISE EXCEPTION
      'Capability authority activation requires all opengeni_app sessions to be stopped'
      USING ERRCODE = '55000';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM capability_operations
    WHERE target_kind IN ('plugin', 'integration', 'skill', 'pack', 'facet_binding')
      AND status IN ('pending', 'running')
  ) THEN
    RAISE EXCEPTION
      'Capability authority activation requires Plugin, Integration, Skill, Pack, and Facet operations to be settled'
      USING ERRCODE = '55000';
  END IF;
END
$maintenance_preflight_guard$;

DO $lock_authority$
DECLARE
  relation_name text;
BEGIN
  FOREACH relation_name IN ARRAY ARRAY[
    'capability_catalog_items',
    'capability_installations',
    'capability_plugins',
    'capability_plugin_versions',
    'capability_facets',
    'capability_skill_facets',
    'capability_skill_files',
    'capability_plugin_installations',
    'capability_facet_installations',
    'capability_component_owners',
    'capability_operations'
  ]
  LOOP
    EXECUTE format('LOCK TABLE %I IN ACCESS EXCLUSIVE MODE', relation_name);
  END LOOP;
END
$lock_authority$;

CREATE OR REPLACE FUNCTION opengeni_private.skill_authority_canonical_json(value jsonb)
RETURNS text
LANGUAGE plpgsql
IMMUTABLE
STRICT
PARALLEL SAFE
AS $canonical_json$
DECLARE
  rendered text;
BEGIN
  CASE jsonb_typeof(value)
    WHEN 'object' THEN
      SELECT COALESCE(
        '{' || string_agg(
          to_jsonb(entry.key)::text || ':' ||
            opengeni_private.skill_authority_canonical_json(entry.value),
          ',' ORDER BY entry.key COLLATE "C"
        ) || '}',
        '{}'
      )
      INTO rendered
      FROM jsonb_each(value) AS entry(key, value);
      RETURN rendered;
    WHEN 'array' THEN
      SELECT COALESCE(
        '[' || string_agg(
          opengeni_private.skill_authority_canonical_json(entry.value),
          ',' ORDER BY entry.ordinality
        ) || ']',
        '[]'
      )
      INTO rendered
      FROM jsonb_array_elements(value) WITH ORDINALITY AS entry(value, ordinality);
      RETURN rendered;
    ELSE
      RETURN value::text;
  END CASE;
END
$canonical_json$;

