        "path": "references/EXAMPLES.md",
        "content": "# Example Test Suite\n\nComplete example testing a VPC module with unit, integration, and mock tests.\n\n## Unit Tests (Plan Mode)\n\n```hcl\n# tests/vpc_module_unit_test.tftest.hcl\n\nvariables {\n  environment = \"test\"\n  aws_region  = \"us-west-2\"\n}\n\nrun \"test_defaults\" {\n  command = plan\n\n  variables {\n    vpc_cidr = \"10.0.0.0/16\"\n    vpc_name = \"test-vpc\"\n  }\n\n  assert {\n    condition     = aws_vpc.main.cidr_block == \"10.0.0.0/16\"\n    error_message = \"VPC CIDR should match input\"\n  }\n\n  assert {\n    condition     = aws_vpc.main.enable_dns_hostnames == true\n    error_message = \"DNS hostnames should be enabled by default\"\n  }\n\n  assert {\n    condition     = aws_vpc.main.tags[\"Name\"] == \"test-vpc\"\n    error_message = \"VPC name tag should match input\"\n  }\n}\n\nrun \"test_subnets\" {\n  command = plan\n\n  variables {\n    vpc_cidr        = \"10.0.0.0/16\"\n    vpc_name        = \"test-vpc\"\n    public_subnets  = [\"10.0.1.0/24\", \"10.0.2.0/24\"]\n    private_subnets = [\"10.0.10.0/24\", \"10.0.11.0/24\"]\n  }\n\n  assert {\n    condition     = length(aws_subnet.public) == 2\n    error_message = \"Should create 2 public subnets\"\n  }\n\n  assert {\n    condition     = length(aws_subnet.private) == 2\n    error_message = \"Should create 2 private subnets\"\n  }\n\n  assert {\n    condition = alltrue([\n      for subnet in aws_subnet.private :\n      subnet.map_public_ip_on_launch == false\n    ])\n    error_message = \"Private subnets should not assign public IPs\"\n  }\n}\n\nrun \"test_outputs\" {\n  command = plan\n\n  variables {\n    vpc_cidr = \"10.0.0.0/16\"\n    vpc_name = \"test-vpc\"\n  }\n\n  assert {\n    condition     = output.vpc_id != \"\"\n    error_message = \"VPC ID output should not be empty\"\n  }\n\n  assert {\n    condition     = can(regex(\"^vpc-\", output.vpc_id))\n    error_message = \"VPC ID should have correct format\"\n  }\n\n  assert {\n    condition     = output.vpc_cidr == \"10.0.0.0/16\"\n    error_message = \"VPC CIDR output should match input\"\n  }\n}\n\nrun \"test_invalid_cidr\" {\n  command = plan\n\n  variables {\n    vpc_cidr = \"invalid\"\n    vpc_name = \"test-vpc\"\n  }\n\n  expect_failures = [\n    var.vpc_cidr\n  ]\n}\n```\n\n## Integration Tests (Apply Mode)\n\n```hcl\n# tests/vpc_module_integration_test.tftest.hcl\n\nvariables {\n  environment = \"integration-test\"\n  aws_region  = \"us-west-2\"\n}\n\nrun \"integration_test_vpc_creation\" {\n  # command defaults to apply — creates real AWS resources\n\n  variables {\n    vpc_cidr = \"10.100.0.0/16\"\n    vpc_name = \"integration-test-vpc\"\n  }\n\n  assert {\n    condition     = aws_vpc.main.id != \"\"\n    error_message = \"VPC should be created with valid ID\"\n  }\n\n  assert {\n    condition     = aws_vpc.main.state == \"available\"\n    error_message = \"VPC should be in available state\"\n  }\n}\n```\n\n## Mock Tests (Plan Mode, No Credentials)\n\n```hcl\n# tests/vpc_module_mock_test.tftest.hcl\n\nmock_provider \"aws\" {\n  mock_resource \"aws_instance\" {\n    defaults = {\n      id            = \"i-1234567890abcdef0\"\n      instance_type = \"t2.micro\"\n      ami           = \"ami-12345678\"\n      public_ip     = \"203.0.113.1\"\n      private_ip    = \"10.0.1.100\"\n    }\n  }\n\n  mock_resource \"aws_vpc\" {\n    defaults = {\n      id                   = \"vpc-12345678\"\n      cidr_block           = \"10.0.0.0/16\"\n      enable_dns_hostnames = true\n      enable_dns_support   = true\n    }\n  }\n\n  mock_resource \"aws_subnet\" {\n    defaults = {\n      id                      = \"subnet-12345678\"\n      vpc_id                  = \"vpc-12345678\"\n      cidr_block              = \"10.0.1.0/24\"\n      availability_zone       = \"us-west-2a\"\n      map_public_ip_on_launch = false\n    }\n  }\n\n  mock_data \"aws_ami\" {\n    defaults = {\n      id   = \"ami-0c55b159cbfafe1f0\"\n      name = \"ubuntu-focal-20.04-amd64\"\n    }\n  }\n\n  mock_data \"aws_availability_zones\" {\n    defaults = {\n      names = [\"us-west-2a\", \"us-west-2b\", \"us-west-2c\"]\n    }\n  }\n}\n\nrun \"test_instance_with_mocks\" {\n  command = plan\n\n  variables {\n    instance_type = \"t2.micro\"\n    ami_id        = \"ami-12345678\"\n  }\n\n  assert {\n    condition     = aws_instance.example.instance_type == \"t2.micro\"\n    error_message = \"Instance type should match input variable\"\n  }\n\n  assert {\n    condition     = aws_instance.example.id == \"i-1234567890abcdef0\"\n    error_message = \"Mock should return consistent instance ID\"\n  }\n}\n\nrun \"test_data_source_with_mocks\" {\n  command = plan\n\n  assert {\n    condition     = data.aws_ami.ubuntu.id == \"ami-0c55b159cbfafe1f0\"\n    error_message = \"Mock data source should return predictable AMI ID\"\n  }\n\n  assert {\n    condition     = length(data.aws_availability_zones.available.names) == 3\n    error_message = \"Should return 3 mocked availability zones\"\n  }\n\n  assert {\n    condition     = contains(data.aws_availability_zones.available.names, \"us-west-2a\")\n    error_message = \"Should include us-west-2a in mocked zones\"\n  }\n}\n\nrun \"test_outputs_with_mocks\" {\n  command = plan\n\n  assert {\n    condition     = output.vpc_id == \"vpc-12345678\"\n    error_message = \"VPC ID output should match mocked value\"\n  }\n\n  assert {\n    condition     = can(regex(\"^vpc-\", output.vpc_id))\n    error_message = \"VPC ID output should have correct format\"\n  }\n}\n\nrun \"test_conditional_resources_with_mocks\" {\n  command = plan\n\n  variables {\n    create_bastion     = true\n    create_nat_gateway = false\n  }\n\n  assert {\n    condition     = length(aws_instance.bastion) == 1\n    error_message = \"Bastion should be created when enabled\"\n  }\n\n  assert {\n    condition     = length(aws_nat_gateway.nat) == 0\n    error_message = \"NAT gateway should not be created when disabled\"\n  }\n}\n\nrun \"test_tag_inheritance_with_mocks\" {\n  command = plan\n\n  variables {\n    common_tags = {\n      Environment = \"test\"\n      ManagedBy   = \"Terraform\"\n    }\n  }\n\n  assert {\n    condition = alltrue([\n      for key in keys(var.common_tags) :\n      contains(keys(aws_instance.example.tags), key)\n    ])\n    error_message = \"All common tags should be present on instance\"\n  }\n}\n\nrun \"test_invalid_cidr_with_mocks\" {\n  command = plan\n\n  variables {\n    vpc_cidr = \"invalid\"\n  }\n\n  expect_failures = [\n    var.vpc_cidr\n  ]\n}\n\nrun \"setup_vpc_with_mocks\" {\n  command = plan\n\n  variables {\n    vpc_cidr = \"10.0.0.0/16\"\n    vpc_name = \"test-vpc\"\n  }\n\n  assert {\n    condition     = aws_vpc.main.cidr_block == \"10.0.0.0/16\"\n    error_message = \"VPC CIDR should match input\"\n  }\n}\n\nrun \"test_subnet_references_vpc_with_mocks\" {\n  command = plan\n\n  variables {\n    vpc_id      = run.setup_vpc_with_mocks.vpc_id\n    subnet_cidr = \"10.0.1.0/24\"\n  }\n\n  assert {\n    condition     = aws_subnet.example.vpc_id == run.setup_vpc_with_mocks.vpc_id\n    error_message = \"Subnet should reference VPC from previous run\"\n  }\n}\n```\n",
        "byte_size": 6609,
        "content_sha256": "e57ef65b6c6545e00f7dc6106c71d44d29e819923ea8e0040efb38fbfbc60f50"
      },
      {
        "path": "references/MOCK_PROVIDERS.md",
        "content": "# Mock Providers\n\nMock providers simulate provider behavior without creating real infrastructure (Terraform 1.7.0+). Use them for fast, credential-free unit tests.\n\n## Basic Mock Provider\n\n```hcl\nmock_provider \"aws\" {\n  mock_resource \"aws_instance\" {\n    defaults = {\n      id            = \"i-1234567890abcdef0\"\n      instance_type = \"t2.micro\"\n      ami           = \"ami-12345678\"\n      public_ip     = \"203.0.113.1\"\n      private_ip    = \"10.0.1.100\"\n    }\n  }\n\n  mock_data \"aws_ami\" {\n    defaults = {\n      id = \"ami-0c55b159cbfafe1f0\"\n    }\n  }\n\n  mock_data \"aws_availability_zones\" {\n    defaults = {\n      names = [\"us-west-2a\", \"us-west-2b\", \"us-west-2c\"]\n    }\n  }\n}\n\nrun \"test_with_mocks\" {\n  command = plan  # Mocks only work with plan mode\n\n  assert {\n    condition     = aws_instance.example.id == \"i-1234567890abcdef0\"\n    error_message = \"Mock instance ID should match\"\n  }\n}\n```\n\n## Aliased Mock Provider\n\n```hcl\nmock_provider \"aws\" {\n  alias = \"mocked\"\n\n  mock_resource \"aws_s3_bucket\" {\n    defaults = {\n      id  = \"test-bucket-12345\"\n      arn = \"arn:aws:s3:::test-bucket-12345\"\n    }\n  }\n}\n\nrun \"test_with_aliased_mock\" {\n  command = plan\n\n  providers = {\n    aws = provider.aws.mocked\n  }\n\n  assert {\n    condition     = aws_s3_bucket.example.id == \"test-bucket-12345\"\n    error_message = \"Bucket ID should match mock\"\n  }\n}\n```\n\n## Common Mock Defaults\n\n```hcl\nmock_provider \"aws\" {\n  mock_resource \"aws_instance\" {\n    defaults = {\n      id                          = \"i-1234567890abcdef0\"\n      arn                         = \"arn:aws:ec2:us-west-2:123456789012:instance/i-1234567890abcdef0\"\n      instance_type               = \"t2.micro\"\n      ami                         = \"ami-12345678\"\n      availability_zone           = \"us-west-2a\"\n      subnet_id                   = \"subnet-12345678\"\n      vpc_security_group_ids      = [\"sg-12345678\"]\n      associate_public_ip_address = true\n      public_ip                   = \"203.0.113.1\"\n      private_ip                  = \"10.0.1.100\"\n      tags                        = {}\n    }\n  }\n\n  mock_resource \"aws_vpc\" {\n    defaults = {\n      id                   = \"vpc-12345678\"\n      arn                  = \"arn:aws:ec2:us-west-2:123456789012:vpc/vpc-12345678\"\n      cidr_block           = \"10.0.0.0/16\"\n      enable_dns_hostnames = true\n      enable_dns_support   = true\n      instance_tenancy     = \"default\"\n      tags                 = {}\n    }\n  }\n\n  mock_resource \"aws_subnet\" {\n    defaults = {\n      id                      = \"subnet-12345678\"\n      arn                     = \"arn:aws:ec2:us-west-2:123456789012:subnet/subnet-12345678\"\n      vpc_id                  = \"vpc-12345678\"\n      cidr_block              = \"10.0.1.0/24\"\n      availability_zone       = \"us-west-2a\"\n      map_public_ip_on_launch = false\n      tags                    = {}\n    }\n  }\n\n  mock_resource \"aws_s3_bucket\" {\n    defaults = {\n      id                 = \"test-bucket-12345\"\n      arn                = \"arn:aws:s3:::test-bucket-12345\"\n      bucket             = \"test-bucket-12345\"\n      bucket_domain_name = \"test-bucket-12345.s3.amazonaws.com\"\n      region             = \"us-west-2\"\n      tags               = {}\n    }\n  }\n\n  mock_data \"aws_ami\" {\n    defaults = {\n      id                  = \"ami-0c55b159cbfafe1f0\"\n      name                = \"ubuntu/images/hvm-ssd/ubuntu-focal-20.04-amd64-server-20210430\"\n      architecture        = \"x86_64\"\n      root_device_type    = \"ebs\"\n      virtualization_type = \"hvm\"\n    }\n  }\n\n  mock_data \"aws_availability_zones\" {\n    defaults = {\n      names    = [\"us-west-2a\", \"us-west-2b\", \"us-west-2c\"]\n      zone_ids = [\"usw2-az1\", \"usw2-az2\", \"usw2-az3\"]\n    }\n  }\n\n  mock_data \"aws_vpc\" {\n    defaults = {\n      id                   = \"vpc-12345678\"\n      cidr_block           = \"10.0.0.0/16\"\n      enable_dns_hostnames = true\n      enable_dns_support   = true\n    }\n  }\n}\n```\n\n## When to Use Mocks\n\n**Good fit:**\n- Testing Terraform logic, conditionals, `for_each`/`count` expressions\n- Validating variable transformations and output calculations\n- Local development without cloud credentials\n- Fast CI/CD feedback loops\n\n**Not a good fit:**\n- Validating actual provider API behavior\n- Testing real resource creation side effects\n- End-to-end integration testing\n\n## Limitations\n\n- **Plan mode only** — mocks don't work with `command = apply`\n- Mock defaults may not reflect real computed attribute values\n- Mocks need manual updates when provider schemas change\n- Can't test real resource dependencies or timing\n",
        "byte_size": 4519,
        "content_sha256": "788a9fcb988df8a207c1251fd971a11d1cd59b6b8e4023907b00a0fee976c001"
      }
    ]
  }
]
  $skill_authority_seed$::jsonb
) AS seed(
  library_id text,
  capability_id text,
  plugin_key text,
  version text,
  name text,
  description text,
  category text,
  tags jsonb,
  source_url text,
  repository_url text,
  source_commit text,
  source_path text,
  source_provenance text,
  content_sha256 text,
  file_count integer,
  total_bytes integer,
  license text,
  manifest jsonb,
  manifest_digest text,
  files jsonb
);

CREATE UNIQUE INDEX skill_authority_library_id_idx
  ON skill_authority_library (library_id);
CREATE UNIQUE INDEX skill_authority_capability_id_idx
  ON skill_authority_library (capability_id);
-- END GENERATED CURATED SKILL LIBRARY SEED

DO $seed_integrity$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM skill_authority_library seed
    WHERE seed.capability_id <> 'skill:' || seed.library_id
      OR seed.plugin_key <> 'skill/library/' || seed.library_id
      OR seed.file_count <> jsonb_array_length(seed.files)
      OR seed.total_bytes <> COALESCE((
        SELECT sum(file.byte_size)
        FROM jsonb_to_recordset(seed.files) AS file(
          path text,
          content text,
          byte_size integer,
          content_sha256 text
        )
      ), 0)
      OR seed.manifest_digest <> encode(
        digest(
          convert_to(
            opengeni_private.skill_authority_canonical_json(seed.manifest),
            'UTF8'
          ),
          'sha256'
        ),
        'hex'
      )
      OR EXISTS (
        SELECT 1
        FROM jsonb_to_recordset(seed.files) AS file(
          path text,
          content text,
          byte_size integer,
          content_sha256 text
        )
        WHERE file.byte_size <> octet_length(convert_to(file.content, 'UTF8'))
          OR file.content_sha256 <> encode(
            digest(convert_to(file.content, 'UTF8'), 'sha256'),
            'hex'
          )
      )
  ) THEN
    RAISE EXCEPTION 'curated Skill authority seed failed immutable integrity validation'
      USING ERRCODE = '23514';
  END IF;
END
$seed_integrity$;

CREATE TEMP TABLE skill_authority_curated_selections ON COMMIT DROP AS
SELECT
  installation.id AS legacy_installation_id,
  installation.account_id,
  installation.workspace_id,
  installation.enabled_at,
  seed.*
FROM capability_installations installation
JOIN skill_authority_library seed
  ON seed.capability_id = installation.capability_id
WHERE installation.kind = 'skill'
  AND installation.status = 'active'
  AND COALESCE(installation.metadata ->> 'platformVersion', '') <> '2'
  AND installation.config ->> 'version' = seed.version
  AND installation.metadata ->> 'libraryId' = seed.library_id
  AND installation.metadata ->> 'libraryVersion' = seed.version
  AND installation.metadata ->> 'contentSha256' = seed.content_sha256
  AND installation.metadata ->> 'sourceCommit' = seed.source_commit
  AND installation.metadata ->> 'provenance' = seed.source_provenance;

CREATE UNIQUE INDEX skill_authority_curated_selection_legacy_idx
  ON skill_authority_curated_selections (legacy_installation_id);

DO $legacy_skill_precondition$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM capability_installations installation
    WHERE installation.kind = 'skill'
      AND installation.status = 'active'
      AND NOT EXISTS (
        SELECT 1
        FROM skill_authority_curated_selections selected
        WHERE selected.legacy_installation_id = installation.id
      )
      AND NOT (
        installation.metadata ->> 'platformVersion' = '2'
        AND CASE
          WHEN installation.metadata ->> 'facetInstallationId'
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
          THEN EXISTS (
            SELECT 1
            FROM capability_facet_installations facet_installation
            JOIN capability_plugin_installations plugin_installation
              ON plugin_installation.id = facet_installation.plugin_installation_id
            JOIN capability_skill_facets skill
              ON skill.facet_id = facet_installation.facet_id
            WHERE facet_installation.id =
                (installation.metadata ->> 'facetInstallationId')::uuid
              AND facet_installation.account_id = installation.account_id
              AND facet_installation.workspace_id = installation.workspace_id
              AND facet_installation.status = 'active'
              AND plugin_installation.account_id = installation.account_id
              AND plugin_installation.workspace_id = installation.workspace_id
              AND plugin_installation.status = 'active'
              AND skill.capability_id = installation.capability_id
              AND EXISTS (
                SELECT 1
                FROM capability_component_owners owner
                WHERE owner.facet_installation_id = facet_installation.id
              )
          )
          ELSE false
        END
      )
  ) THEN
    RAISE EXCEPTION
      'an active legacy Skill installation is neither an exact curated selection nor a valid normalized Skill projection'
      USING ERRCODE = '23514';
  END IF;
END
$legacy_skill_precondition$;

DO $materialize_curated_skill_selections$
DECLARE
  selected record;
  v_plugin_id uuid;
  v_plugin_version_id uuid;
  v_skill_facet_id uuid;
  v_plugin_installation_id uuid;
  v_facet_installation_id uuid;
  existing_plugin_version record;
  existing_facet record;
  existing_skill record;
  existing_plugin_installation record;
  existing_facet_installation record;
BEGIN
  FOR selected IN
    SELECT *
    FROM skill_authority_curated_selections
    ORDER BY workspace_id, library_id
  LOOP
    SELECT plugin.id
    INTO v_plugin_id
    FROM capability_plugins plugin
    WHERE plugin.workspace_id = selected.workspace_id
      AND plugin.plugin_key = selected.plugin_key
    FOR UPDATE;

    IF v_plugin_id IS NULL THEN
      INSERT INTO capability_plugins (
        plugin_key,
        account_id,
        workspace_id,
        name,
        description,
        category,
        tags,
        provenance
      ) VALUES (
        selected.plugin_key,
        selected.account_id,
        selected.workspace_id,
        selected.name,
        selected.description,
        selected.category,
        selected.tags,
        'platform'
      )
      RETURNING id INTO v_plugin_id;
    ELSE
      IF EXISTS (
        SELECT 1
        FROM capability_plugins plugin
        WHERE plugin.id = v_plugin_id
          AND plugin.account_id IS DISTINCT FROM selected.account_id
      ) THEN
        RAISE EXCEPTION 'curated Skill Plugin tenant mismatch for %', selected.plugin_key
          USING ERRCODE = '23514';
      END IF;
      UPDATE capability_plugins
      SET name = selected.name,
          description = selected.description,
          category = selected.category,
          tags = selected.tags,
          provenance = 'platform',
          updated_at = now()
      WHERE id = v_plugin_id
        AND (
          name IS DISTINCT FROM selected.name
          OR description IS DISTINCT FROM selected.description
          OR category IS DISTINCT FROM selected.category
          OR tags IS DISTINCT FROM selected.tags
          OR provenance IS DISTINCT FROM 'platform'
        );
    END IF;

    SELECT version.*
    INTO existing_plugin_version
    FROM capability_plugin_versions version
    WHERE version.plugin_id = v_plugin_id
      AND version.version = selected.version
    FOR UPDATE;

    IF NOT FOUND THEN
      INSERT INTO capability_plugin_versions (
        plugin_id,
        version,
        manifest_digest,
        manifest,
        status
      ) VALUES (
        v_plugin_id,
        selected.version,
        selected.manifest_digest,
        selected.manifest,
        'published'
      )
      RETURNING id INTO v_plugin_version_id;
    ELSE
      IF existing_plugin_version.manifest_digest <> selected.manifest_digest
        OR existing_plugin_version.manifest IS DISTINCT FROM selected.manifest
      THEN
        RAISE EXCEPTION 'curated Skill immutable version conflict for %@%',
          selected.library_id,
          selected.version
          USING ERRCODE = '23514';
      END IF;
      v_plugin_version_id := existing_plugin_version.id;
      UPDATE capability_plugin_versions
      SET status = 'published'
      WHERE id = v_plugin_version_id
        AND status IS DISTINCT FROM 'published';
    END IF;

    SELECT facet.*
    INTO existing_facet
    FROM capability_facets facet
    WHERE facet.plugin_version_id = v_plugin_version_id
      AND facet.facet_key = 'skill';

    IF NOT FOUND THEN
      INSERT INTO capability_facets (
        plugin_version_id,
        facet_key,
        kind,
        activation_mode,
        required
      ) VALUES (
        v_plugin_version_id,
        'skill',
        'skill',
        'workspace_managed',
        true
      )
      RETURNING id INTO v_skill_facet_id;
    ELSE
      IF existing_facet.kind <> 'skill'
        OR existing_facet.activation_mode <> 'workspace_managed'
        OR existing_facet.required IS DISTINCT FROM true
      THEN
        RAISE EXCEPTION 'curated Skill immutable Facet conflict for %', selected.library_id
          USING ERRCODE = '23514';
      END IF;
      v_skill_facet_id := existing_facet.id;
    END IF;

    SELECT skill.*
    INTO existing_skill
    FROM capability_skill_facets skill
    WHERE skill.facet_id = v_skill_facet_id;

    IF NOT FOUND THEN
      INSERT INTO capability_skill_facets (
        facet_id,
        capability_id,
        name,
        description,
        source_url,
        source_commit,
        source_path,
        content_sha256,
        file_count,
        total_bytes,
        license
      ) VALUES (
        v_skill_facet_id,
        selected.capability_id,
        selected.name,
        selected.description,
        selected.source_url,
        selected.source_commit,
        selected.source_path,
        selected.content_sha256,
        selected.file_count,
        selected.total_bytes,
        selected.license
      );

      INSERT INTO capability_skill_files (
        skill_facet_id,
        path,
        content,
        byte_size,
        content_sha256
      )
      SELECT
        v_skill_facet_id,
        file.path,
        file.content,
        file.byte_size,
        file.content_sha256
      FROM jsonb_to_recordset(selected.files) AS file(
        path text,
        content text,
        byte_size integer,
        content_sha256 text
      );
    ELSE
      IF existing_skill.capability_id <> selected.capability_id
        OR existing_skill.name <> selected.name
        OR existing_skill.description <> selected.description
        OR existing_skill.source_url <> selected.source_url
        OR existing_skill.source_commit <> selected.source_commit
        OR existing_skill.source_path <> selected.source_path
        OR existing_skill.content_sha256 <> selected.content_sha256
        OR existing_skill.file_count <> selected.file_count
        OR existing_skill.total_bytes <> selected.total_bytes
        OR existing_skill.license IS DISTINCT FROM selected.license
      THEN
        RAISE EXCEPTION 'curated Skill immutable artifact conflict for %', selected.library_id
          USING ERRCODE = '23514';
      END IF;
    END IF;

    IF (SELECT count(*) FROM capability_skill_files file WHERE file.skill_facet_id = v_skill_facet_id)
      <> selected.file_count
      OR EXISTS (
        SELECT 1
        FROM jsonb_to_recordset(selected.files) AS seeded_file(
          path text,
          content text,
          byte_size integer,
          content_sha256 text
        )
        LEFT JOIN capability_skill_files stored_file
          ON stored_file.skill_facet_id = v_skill_facet_id
         AND stored_file.path = seeded_file.path
        WHERE stored_file.id IS NULL
          OR stored_file.content <> seeded_file.content
          OR stored_file.byte_size <> seeded_file.byte_size
          OR stored_file.content_sha256 <> seeded_file.content_sha256
      )
    THEN
      RAISE EXCEPTION 'curated Skill immutable file conflict for %', selected.library_id
        USING ERRCODE = '23514';
    END IF;

    SELECT installation.*
    INTO existing_plugin_installation
    FROM capability_plugin_installations installation
    WHERE installation.workspace_id = selected.workspace_id
      AND installation.plugin_id = v_plugin_id
    FOR UPDATE;

    IF NOT FOUND THEN
      INSERT INTO capability_plugin_installations (
        account_id,
        workspace_id,
        plugin_id,
        plugin_version_id,
        status,
        installed_by_subject_id,
        installed_at,
        updated_at
      ) VALUES (
        selected.account_id,
        selected.workspace_id,
        v_plugin_id,
        v_plugin_version_id,
        'active',
        'migration:0233',
        selected.enabled_at,
        now()
      )
      RETURNING id INTO v_plugin_installation_id;
    ELSE
      v_plugin_installation_id := existing_plugin_installation.id;
      IF existing_plugin_installation.plugin_version_id <> v_plugin_version_id THEN
        IF EXISTS (
          SELECT 1
          FROM capability_facet_installations facet_installation
          JOIN capability_component_owners owner
            ON owner.facet_installation_id = facet_installation.id
          WHERE facet_installation.plugin_installation_id = v_plugin_installation_id
            AND NOT (
              owner.owner_kind = 'direct'
              AND owner.owner_id = selected.capability_id
            )
        ) THEN
          RAISE EXCEPTION 'curated Skill version is pinned by another owner for %',
            selected.library_id
            USING ERRCODE = '23514';
        END IF;
        DELETE FROM capability_facet_installations
        WHERE plugin_installation_id = existing_plugin_installation.id;
      END IF;
      IF existing_plugin_installation.plugin_version_id <> v_plugin_version_id
        OR existing_plugin_installation.status <> 'active'
      THEN
        UPDATE capability_plugin_installations
        SET plugin_version_id = v_plugin_version_id,
            status = 'active',
            version = version + 1,
            installed_by_subject_id = 'migration:0233',
            installed_at = selected.enabled_at,
            updated_at = now()
        WHERE id = v_plugin_installation_id;
      END IF;
    END IF;

    SELECT installation.*
    INTO existing_facet_installation
    FROM capability_facet_installations installation
    WHERE installation.plugin_installation_id = v_plugin_installation_id
      AND installation.facet_id = v_skill_facet_id
    FOR UPDATE;

    IF NOT FOUND THEN
      INSERT INTO capability_facet_installations (
        account_id,
        workspace_id,
        plugin_installation_id,
        facet_id,
        status,
        config
      ) VALUES (
        selected.account_id,
        selected.workspace_id,
        v_plugin_installation_id,
        v_skill_facet_id,
        'active',
        '{}'::jsonb
      )
      RETURNING id INTO v_facet_installation_id;
    ELSE
      v_facet_installation_id := existing_facet_installation.id;
      IF existing_facet_installation.account_id <> selected.account_id
        OR existing_facet_installation.workspace_id <> selected.workspace_id
      THEN
        RAISE EXCEPTION 'curated Skill Facet installation tenant mismatch for %',
          selected.library_id
          USING ERRCODE = '23514';
      END IF;
      IF existing_facet_installation.status <> 'active'
        OR existing_facet_installation.config IS DISTINCT FROM '{}'::jsonb
        OR existing_facet_installation.attention_code IS NOT NULL
      THEN
        UPDATE capability_facet_installations
        SET status = 'active',
            config = '{}'::jsonb,
            version = version + 1,
            attention_code = NULL,
            updated_at = now()
        WHERE id = v_facet_installation_id;
      END IF;
    END IF;

    INSERT INTO capability_component_owners (
      account_id,
      workspace_id,
      facet_installation_id,
      owner_kind,
      owner_id,
      removable
    ) VALUES (
      selected.account_id,
      selected.workspace_id,
      v_facet_installation_id,
      'direct',
      selected.capability_id,
      true
    )
    ON CONFLICT (facet_installation_id, owner_kind, owner_id) DO NOTHING;
  END LOOP;
END
$materialize_curated_skill_selections$;

DO $curated_skill_postcondition$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM skill_authority_curated_selections selected
    WHERE NOT EXISTS (
      SELECT 1
      FROM capability_plugins plugin
      JOIN capability_plugin_versions version
        ON version.plugin_id = plugin.id
       AND version.version = selected.version
       AND version.manifest_digest = selected.manifest_digest
      JOIN capability_facets facet
        ON facet.plugin_version_id = version.id
       AND facet.facet_key = 'skill'
       AND facet.kind = 'skill'
      JOIN capability_skill_facets skill
        ON skill.facet_id = facet.id
       AND skill.capability_id = selected.capability_id
       AND skill.content_sha256 = selected.content_sha256
      JOIN capability_plugin_installations plugin_installation
        ON plugin_installation.plugin_id = plugin.id
       AND plugin_installation.plugin_version_id = version.id
       AND plugin_installation.workspace_id = selected.workspace_id
       AND plugin_installation.status = 'active'
      JOIN capability_facet_installations facet_installation
        ON facet_installation.plugin_installation_id = plugin_installation.id
       AND facet_installation.facet_id = facet.id
       AND facet_installation.status = 'active'
      JOIN capability_component_owners owner
        ON owner.facet_installation_id = facet_installation.id
       AND owner.owner_kind = 'direct'
       AND owner.owner_id = selected.capability_id
      WHERE plugin.workspace_id = selected.workspace_id
        AND plugin.account_id = selected.account_id
        AND plugin.plugin_key = selected.plugin_key
    )
  ) THEN
    RAISE EXCEPTION 'curated Skill authority migration did not converge'
      USING ERRCODE = '23514';
  END IF;
END
$curated_skill_postcondition$;

DELETE FROM capability_installations
WHERE kind <> 'mcp';

DELETE FROM capability_catalog_items
WHERE kind <> 'mcp';

ALTER TABLE capability_installations
  DROP CONSTRAINT IF EXISTS capability_installations_kind_authority_chk;
ALTER TABLE capability_installations
  ADD CONSTRAINT capability_installations_kind_authority_chk
  CHECK (kind = 'mcp') NOT VALID;
ALTER TABLE capability_installations
  VALIDATE CONSTRAINT capability_installations_kind_authority_chk;

ALTER TABLE capability_catalog_items
  DROP CONSTRAINT IF EXISTS capability_catalog_items_kind_authority_chk;
ALTER TABLE capability_catalog_items
  ADD CONSTRAINT capability_catalog_items_kind_authority_chk
  CHECK (kind = 'mcp') NOT VALID;
ALTER TABLE capability_catalog_items
  VALIDATE CONSTRAINT capability_catalog_items_kind_authority_chk;

COMMENT ON TABLE capability_catalog_items IS
  'MCP discovery catalog only. Skills, Plugins, Integration Definitions, and Packs use their dedicated authoritative ledgers.';
COMMENT ON TABLE capability_installations IS
  'MCP enablement only. Skill, Plugin, Integration Definition, and Pack lifecycle is owned by normalized domain installations.';
COMMENT ON TABLE capability_plugins IS
  'Authoritative normalized Plugin definitions for Skills, Plugins, and Integration Definitions.';
COMMENT ON TABLE capability_plugin_installations IS
  'Authoritative workspace Plugin-version lifecycle for Skills, Plugins, and Integration Definitions.';

DO $authority_postcondition$
BEGIN
  IF EXISTS (SELECT 1 FROM capability_installations WHERE kind <> 'mcp')
    OR EXISTS (SELECT 1 FROM capability_catalog_items WHERE kind <> 'mcp')
  THEN
    RAISE EXCEPTION 'generic Capability authority cutover did not converge'
      USING ERRCODE = '23514';
  END IF;
END
$authority_postcondition$;

DROP FUNCTION opengeni_private.skill_authority_canonical_json(jsonb);